static const s32 gAreaPresetCount = sizeof(gAreaPresets) / sizeof(gAreaPresets[0]);

void register_all_area_presets(void) {
    for (s32 i = 0; i < gAreaPresetCount; i++) {
        register_enhanced_shading_preset(&gAreaPresets[i]);
    }
}
